WITH with_dims AS (SELECT s.id, s.session_id, s.event_type, s.page, s.duration_sec, b.country FROM web_events s INNER JOIN sessions b ON s.session_id = b.id WHERE b.browser != 'Chrome') SELECT s.id, s.session_id, s.page, s.duration_sec, (SELECT SUM(x.duration_sec) FROM web_events x WHERE x.session_id = s.session_id) AS sum_web_event_duration_sec FROM with_dims s ORDER BY session_id DESC NULLS LAST
